SELECT CASE WHEN budget >= 4131000 THEN 'high' WHEN budget >= 1344000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, ROUND((100 * SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_london FROM departments WHERE dept_name IS NULL AND budget < 2469000 GROUP BY budget_bucket, location HAVING ROUND((100 * SUM(CASE WHEN location = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) >= 39 ORDER BY location DESC
